// 삼각형 BVH 기반 표면 거리·내부 판정과 관통 검사의 수치 도구입니다.
using System;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;
namespace K2ValidationV003C {
public sealed class Geometry {
 public readonly Transform transform;public readonly Vector3[] vertices;public readonly int[] triangles;public int boundaryEdges;public int nonManifoldEdges;
 sealed class Node {public Bounds box;public Node left,right;public int[] ids;}
 readonly Node root;
 public Geometry(Mesh mesh,Transform t){transform=t;vertices=mesh.vertices;triangles=mesh.triangles;root=Build(Enumerable.Range(0,triangles.Length/3).ToArray());Topology();}
 Bounds TriBounds(int i){var b=new Bounds(vertices[triangles[3*i]],Vector3.zero);b.Encapsulate(vertices[triangles[3*i+1]]);b.Encapsulate(vertices[triangles[3*i+2]]);return b;}
 Node Build(int[] ids){var n=new Node();if(ids.Length==0){n.ids=ids;return n;}n.box=TriBounds(ids[0]);foreach(var i in ids)n.box.Encapsulate(TriBounds(i));if(ids.Length<=12){n.ids=ids;return n;}var size=n.box.size;int axis=size.x>size.y?(size.x>size.z?0:2):(size.y>size.z?1:2);Array.Sort(ids,(a,b)=>TriBounds(a).center[axis].CompareTo(TriBounds(b).center[axis]));int m=ids.Length/2;n.left=Build(ids.Take(m).ToArray());n.right=Build(ids.Skip(m).ToArray());return n;}
 void Topology(){var welded=new Dictionary<string,int>();var map=new int[vertices.Length];for(int i=0;i<vertices.Length;i++){var v=vertices[i];string k=Math.Round(v.x*1e6)+":"+Math.Round(v.y*1e6)+":"+Math.Round(v.z*1e6);if(!welded.ContainsKey(k))welded[k]=welded.Count;map[i]=welded[k];}var edges=new Dictionary<long,int>();for(int i=0;i<triangles.Length;i+=3){for(int j=0;j<3;j++){int a=map[triangles[i+j]],b=map[triangles[i+(j+1)%3]];if(a==b)continue;long key=((long)Math.Min(a,b)<<32)|(uint)Math.Max(a,b);edges[key]=edges.ContainsKey(key)?edges[key]+1:1;}}boundaryEdges=edges.Count(p=>p.Value==1);nonManifoldEdges=edges.Count(p=>p.Value>2);}
 public static Vector3 Closest(Vector3 p,Vector3 a,Vector3 b,Vector3 c){var ab=b-a;var ac=c-a;var ap=p-a;float d1=Vector3.Dot(ab,ap),d2=Vector3.Dot(ac,ap);if(d1<=0&&d2<=0)return a;var bp=p-b;float d3=Vector3.Dot(ab,bp),d4=Vector3.Dot(ac,bp);if(d3>=0&&d4<=d3)return b;float vc=d1*d4-d3*d2;if(vc<=0&&d1>=0&&d3<=0)return a+d1/(d1-d3)*ab;var cp=p-c;float d5=Vector3.Dot(ab,cp),d6=Vector3.Dot(ac,cp);if(d6>=0&&d5<=d6)return c;float vb=d5*d2-d1*d6;if(vb<=0&&d2>=0&&d6<=0)return a+d2/(d2-d6)*ac;float va=d3*d6-d5*d4;if(va<=0&&(d4-d3)>=0&&(d5-d6)>=0)return b+(d4-d3)/(d4-d3+d5-d6)*(c-b);float sum=va+vb+vc;if(Mathf.Abs(sum)<1e-20f)return a;return a+ab*(vb/sum)+ac*(vc/sum);}
 void Nearest(Node n,Vector3 p,ref float best,ref Vector3 point){if(n.box.SqrDistance(p)>best)return;if(n.ids!=null){foreach(var i in n.ids){var q=Closest(p,vertices[triangles[i*3]],vertices[triangles[i*3+1]],vertices[triangles[i*3+2]]);float d=(p-q).sqrMagnitude;if(d<best){best=d;point=q;}}return;}var a=n.left;var b=n.right;if(a.box.SqrDistance(p)>b.box.SqrDistance(p)){a=n.right;b=n.left;}Nearest(a,p,ref best,ref point);Nearest(b,p,ref best,ref point);}
 public Vector3 ClosestWorld(Vector3 world){var p=transform.InverseTransformPoint(world);float best=float.PositiveInfinity;var q=Vector3.zero;Nearest(root,p,ref best,ref q);return transform.TransformPoint(q);}
 public float Distance(Vector3 world){var p=transform.InverseTransformPoint(world);float best=float.PositiveInfinity;var q=Vector3.zero;Nearest(root,p,ref best,ref q);return Vector3.Distance(world,transform.TransformPoint(q));}
 static bool Hit(Vector3 p,Vector3 dir,Vector3 a,Vector3 b,Vector3 c,out float t){t=0;var e1=b-a;var e2=c-a;var h=Vector3.Cross(dir,e2);float det=Vector3.Dot(e1,h);if(Mathf.Abs(det)<1e-10f)return false;float inv=1/det;var s=p-a;float u=Vector3.Dot(s,h)*inv;if(u<-.000001f||u>1.000001f)return false;var q=Vector3.Cross(s,e1);float v=Vector3.Dot(dir,q)*inv;if(v<-.000001f||u+v>1.000001f)return false;t=Vector3.Dot(e2,q)*inv;return t>1e-7f;}
 void Hits(Node n,Ray ray,List<float> hits){if(!n.box.IntersectRay(ray))return;if(n.ids!=null){foreach(var i in n.ids){float t;if(Hit(ray.origin,ray.direction,vertices[triangles[3*i]],vertices[triangles[3*i+1]],vertices[triangles[3*i+2]],out t))hits.Add(t);}return;}Hits(n.left,ray,hits);Hits(n.right,ray,hits);}
 public float SignedDistance(Vector3 world){float d=Distance(world);var p=transform.InverseTransformPoint(world);if(!root.box.Contains(p))return d;var hits=new List<float>();Hits(root,new Ray(p,new Vector3(.834123f,.392123f,.387913f).normalized),hits);hits.Sort();int count=0;float last=-100;foreach(float h in hits)if(h-last>1e-6f){count++;last=h;}return count%2==1?-d:d;}
 public bool Closed=>boundaryEdges==0&&nonManifoldEdges==0;
 public float SpherePenetration(Vector3 center,float radius)=>Mathf.Max(0,radius-SignedDistance(center));
 public static float Surface(Vector3 p,IEnumerable<Geometry> target){float d=float.PositiveInfinity;foreach(var g in target)d=Mathf.Min(d,g.Distance(p));return d;}
 public static void SelfTest(){var cube=GameObject.CreatePrimitive(PrimitiveType.Cube);var g=new Geometry(cube.GetComponent<MeshFilter>().sharedMesh,cube.transform);if(!g.Closed)throw new Exception("cube topology test failed");if(Mathf.Abs(g.SignedDistance(Vector3.zero)+.5f)>.00001f)throw new Exception("inside signed distance test failed");if(Mathf.Abs(g.SignedDistance(new Vector3(.502f,0,0))-.002f)>.00001f)throw new Exception("2mm outside test failed");if(Mathf.Abs(g.SpherePenetration(new Vector3(.53f,0,0),.04f)-.01f)>.00001f)throw new Exception("sphere penetration test failed");UnityEngine.Object.DestroyImmediate(cube);}
 public struct Penetration {public float lower,upper;public int tested,unresolved;}
 public Penetration CheckAgainst(Geometry solid,float limit,int budget=10000){var r=new Penetration();for(int i=0;i<triangles.Length;i+=3){var a=transform.TransformPoint(vertices[triangles[i]]);var b=transform.TransformPoint(vertices[triangles[i+1]]);var c=transform.TransformPoint(vertices[triangles[i+2]]);CheckTriangle(a,b,c,solid,limit,0,budget,ref r);if(r.lower>limit||r.tested>budget)break;}if(!solid.Closed)r.unresolved++;return r;}
 static void CheckTriangle(Vector3 a,Vector3 b,Vector3 c,Geometry solid,float limit,int level,int budget,ref Penetration r){var p=(a+b+c)/3;float radius=Mathf.Max(Vector3.Distance(p,a),Mathf.Max(Vector3.Distance(p,b),Vector3.Distance(p,c)));float sd=solid.SignedDistance(p);r.tested++;float lower=Mathf.Max(0,-sd),upper=Mathf.Max(0,-sd+radius);r.lower=Mathf.Max(r.lower,lower);if(upper<=limit){r.upper=Mathf.Max(r.upper,upper);return;}if(lower>limit){r.upper=Mathf.Max(r.upper,upper);return;}if(level>=10||r.tested>budget){r.unresolved++;r.upper=Mathf.Max(r.upper,upper);return;}var ab=(a+b)/2;var bc=(b+c)/2;var ca=(c+a)/2;CheckTriangle(a,ab,ca,solid,limit,level+1,budget,ref r);CheckTriangle(ab,b,bc,solid,limit,level+1,budget,ref r);CheckTriangle(ca,bc,c,solid,limit,level+1,budget,ref r);CheckTriangle(ab,bc,ca,solid,limit,level+1,budget,ref r);}
}
}
